//! An Xtensa disassembler generated from LLVM's `TableGen` records.
//!
//! The instruction table (`table.rs`) is generated by `tools/gen_table.py`
//! from LLVM 22.1.8's Xtensa target. Operand decoding and printing follow
//! LLVM's `XtensaDisassembler.cpp` and `XtensaInstPrinter.cpp`, and the
//! special and user register tables were read from `llvm-mc --triple=xtensa
//! -mcpu=esp32`. Output matches that `llvm-mc` on every encoding; see the
//! README for how that is checked.

mod table;
#[cfg(target_arch = "wasm32")]
mod web;

use std::fmt::Write as _;

/// A bit field of an encoding: `len` bits from instruction bit `at`, placed
/// at bit `to` of the operand value.
pub struct Field(pub u8, pub u8, pub u8);

/// Operand kinds, named after LLVM's operand classes.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Ar,
    Fpr,
    Br,
    Mr,
    Mr01,
    Mr23,
    Sr,
    Ur,
    Mem8,
    Mem16,
    Mem32,
    Mem32n,
    Branch,
    Loop,
    Call,
    Jump,
    L32r,
    Imm8,
    Imm8Sh8,
    Imm12,
    Uimm4,
    Uimm5,
    Imm1To16,
    Imm1nTo15,
    Imm32nTo95,
    Imm8nTo7,
    Imm64nTo4n,
    Entry,
    Shimm1To31,
    B4const,
    B4constu,
    Imm7To22,
}

/// One instruction encoding: `word & mask == bits`.
pub struct Spec {
    pub mnemonic: &'static str,
    /// Operand syntax with `{}` for each operand, as in LLVM's `AsmString`.
    pub syntax: &'static str,
    pub mask: u32,
    pub bits: u32,
    pub operands: &'static [(Kind, &'static [Field])],
}

/// How branch-like targets are printed.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Targets {
    /// `. +12`, relative to the instruction, as `llvm-mc` prints them.
    Relative,
    /// Absolute addresses, as `llvm-objdump` prints them.
    Absolute,
}

/// A decoded instruction.
pub struct Insn {
    pub size: usize,
    pub mnemonic: &'static str,
    /// The operands, printed.
    pub operands: String,
}

