fn lookup(table: &[(u32, &'static str)], n: u32) -> Option<&'static str> {
    table.iter().find(|(k, _)| *k == n).map(|(_, name)| *name)
}

fn special_register(mnemonic: &str, n: u32) -> Option<&'static str> {
    let extra: &[(u32, &str)] = match mnemonic {
        "rsr" => &SR_READ_EXTRA,
        "wsr" => &SR_WRITE_EXTRA,
        _ => &[],
    };
    lookup(&SR_COMMON, n)
        .or_else(|| lookup(&SR_MISC, n))
        .or_else(|| lookup(extra, n))
}

const fn sext(v: u32, bits: u32) -> i64 {
    let shift = 64 - bits;
    ((v as i64) << shift) >> shift
}

fn field(word: u32, fields: &[Field]) -> u32 {
    fields.iter().fold(0, |v, &Field(at, len, to)| {
        v | (((word >> at) & ((1 << len) - 1)) << to)
    })
}

/// Print a PC-relative offset (from the instruction at `address`).
fn pcrel(out: &mut String, address: u32, offset: i64, targets: Targets) {
    match targets {
        Targets::Relative if offset > 0 => write!(out, ". +{offset}"),
        Targets::Relative => write!(out, ". {offset}"),
        Targets::Absolute => {
            write!(out, "{:#x}", (i64::from(address) + offset) as u32)
        }
    }
    .expect("writing to a String cannot fail");
}

/// Print one operand, or `None` when LLVM rejects the value.
fn operand(
    out: &mut String,
    spec: &Spec,
    kind: Kind,
    v: u32,
    address: u32,
    targets: Targets,
) -> Option<()> {
    let mut put =
        |s: std::fmt::Arguments<'_>| out.write_fmt(s).expect("writing to a String cannot fail");
    match kind {
        Kind::Ar => put(format_args!("a{v}")),
        Kind::Fpr => put(format_args!("f{v}")),
        Kind::Br => put(format_args!("b{v}")),
        Kind::Mr => put(format_args!("m{v}")),
        Kind::Mr01 if v < 2 => put(format_args!("m{v}")),
        Kind::Mr23 if v < 2 => put(format_args!("m{}", v + 2)),
        Kind::Sr => put(format_args!("{}", special_register(spec.mnemonic, v)?)),
        Kind::Ur => put(format_args!("{}", lookup(&UR, v)?)),
        Kind::Mem8 => put(format_args!("a{}, {}", v & 0xf, (v >> 4) & 0xff)),
        Kind::Mem16 => put(format_args!("a{}, {}", v & 0xf, (v >> 3) & 0x1fe)),
        Kind::Mem32 => put(format_args!("a{}, {}", v & 0xf, (v >> 2) & 0x3fc)),
        Kind::Mem32n => put(format_args!("a{}, {}", v & 0xf, (v >> 2) & 0x3c)),
        Kind::Branch => {
            // beqz, bgez, bltz and bnez carry 12 bits; every other branch 8.
            let bits = if field_width(spec, kind) == 12 { 12 } else { 8 };
            pcrel(out, address, sext(v, bits) + 4, targets);
        }
        Kind::Loop => pcrel(out, address, i64::from(v) + 4, targets),
        Kind::Jump => pcrel(out, address, sext(v, 18) + 4, targets),
        Kind::Call => {
            let val = sext(v << 2, 20) + i64::from(address & 3) + 4;
            match targets {
                Targets::Relative if val > 0 => put(format_args!(". +{val}")),
                Targets::Relative => put(format_args!(". {val}")),
                Targets::Absolute => {
                    let target = i64::from(address & !3) + (val & !3);
                    put(format_args!("{:#x}", target as u32));
                }
            }
        }
        Kind::L32r => {
            let value = sext((v << 2) + 0x40000 + (address & 3), 17);
            match targets {
                Targets::Relative => {
                    let off = value & 3;
                    pcrel(out, address, value - off + (((off + 3) & 4) - off), targets);
                }
                Targets::Absolute => {
                    let target = i64::from((address + 3) & !3) + (value & !3);
                    put(format_args!("{:#x}", target as u32));
                }
            }
        }
        Kind::Imm8 => put(format_args!("{}", sext(v, 8))),
        Kind::Imm8Sh8 => put(format_args!("{}", sext(v << 8, 16))),
        Kind::Imm12 => put(format_args!("{}", sext(v, 12))),
        Kind::Uimm4 | Kind::Uimm5 | Kind::Entry => put(format_args!("{v}")),
        Kind::Imm1To16 => put(format_args!("{}", v + 1)),
        Kind::Imm1nTo15 => put(format_args!("{}", if v == 0 { -1 } else { i64::from(v) })),
        Kind::Imm32nTo95 => {
            put(format_args!(
                "{}",
                if v & 0x60 == 0x60 {
                    i64::from(v) - 128
                } else {
                    i64::from(v)
                }
            ));
        }
        Kind::Imm8nTo7 => put(format_args!(
            "{}",
            if v > 7 {
                i64::from(v) - 16
            } else {
                i64::from(v)
            }
        )),
        Kind::Imm64nTo4n => put(format_args!("{}", i64::from(v) - 64)),
        Kind::Shimm1To31 => put(format_args!("{}", 32 - v)),
        Kind::B4const => put(format_args!("{}", B4CONST[v as usize])),
        Kind::B4constu => put(format_args!("{}", B4CONSTU[v as usize])),
        Kind::Imm7To22 => put(format_args!("{}", v + 7)),
        Kind::Mr01 | Kind::Mr23 => return None,
    }
    Some(())
}

fn field_width(spec: &Spec, kind: Kind) -> u32 {
    spec.operands
        .iter()
        .find(|(k, _)| *k == kind)
        .map_or(0, |(_, fs)| fs.iter().map(|f| u32::from(f.1)).sum())
}

fn render(
    spec: &'static Spec,
    word: u32,
    size: usize,
    address: u32,
    targets: Targets,
) -> Option<Insn> {
    let mut printed = Vec::with_capacity(spec.operands.len());
    for &(kind, fields) in spec.operands {
        let mut s = String::new();
        operand(&mut s, spec, kind, field(word, fields), address, targets)?;
        printed.push(s);
    }
    let mut operands = String::new();
    let mut parts = spec.syntax.split("{}");
    operands.push_str(parts.next().unwrap_or_default());
    for (part, value) in parts.zip(&printed) {
        operands.push_str(value);
        operands.push_str(part);
    }
    Some(Insn {
        size,
        mnemonic: spec.mnemonic,
        operands: operands.trim().to_string(),
    })
}

/// Decode the instruction at the start of `bytes`, located at `address`.
/// Like LLVM, the 16-bit table is tried first, then the 24-bit one.
#[must_use]
pub fn decode(bytes: &[u8], address: u32, targets: Targets) -> Option<Insn> {
    if let [b0, b1, rest @ ..] = bytes {
        let word = u32::from(*b0) | u32::from(*b1) << 8;
        if let Some(spec) = table::NARROW.iter().find(|s| word & s.mask == s.bits) {
            return render(spec, word, 2, address, targets);
        }
        let b2 = *rest.first()?;
        let word = word | u32::from(b2) << 16;
        let spec = table::WIDE.iter().find(|s| word & s.mask == s.bits)?;
        return render(spec, word, 3, address, targets);
    }
    None
}

/// One line of a listing: address, bytes, and the instruction or `None`
/// where nothing decodes (one byte is skipped).
pub struct Line {
    pub address: u32,
    pub bytes: Vec<u8>,
    pub insn: Option<Insn>,
}

/// Disassemble a byte buffer that starts at `base`.
#[must_use]
pub fn disassemble(code: &[u8], base: u32, targets: Targets) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut at = 0;
    while at < code.len() {
        let address = base.wrapping_add(at as u32);
        let insn = decode(&code[at..], address, targets);
        let size = insn.as_ref().map_or(1, |i| i.size);
        let end = (at + size).min(code.len());
        lines.push(Line {
            address,
            bytes: code[at..end].to_vec(),
            insn,
        });
        at = end;
    }
    lines
}

/// Most bytes the listing decodes; more input is cut off with a note.
pub const MAX_BYTES: usize = 4096;

/// Parse hex bytes: `0x` and `\x` prefixes, spaces, commas and newlines are
/// all accepted, as is one long run like `36412081`. `#` starts a comment.
///
/// # Errors
///
/// A message naming the first character that is not hex.
pub fn parse_hex(text: &str) -> Result<Vec<u8>, String> {
    let mut digits = String::new();
    for line in text.lines() {
        let line = line.split('#').next().unwrap_or_default();
        for token in line.split(|c: char| c.is_whitespace() || c == ',') {
            let token = token.trim_start_matches("0x").trim_start_matches("0X");
            for part in token.split("\\x") {
                if let Some(bad) = part.chars().find(|c| !c.is_ascii_hexdigit()) {
                    return Err(format!("not a hex digit: {bad:?}"));
                }
                if part.len() % 2 == 1 {
                    return Err(format!("odd number of hex digits in {part:?}"));
                }
                digits.push_str(part);
            }
        }
    }
    (0..digits.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&digits[i..i + 2], 16).map_err(|e| e.to_string()))
        .collect()
}

/// Parse a base address, with or without `0x`.
///
/// # Errors
///
/// A message when it is not a 32-bit hex number.
pub fn parse_address(text: &str) -> Result<u32, String> {
    let t = text.trim();
    let t = t
        .strip_prefix("0x")
        .or_else(|| t.strip_prefix("0X"))
        .unwrap_or(t);
    if t.is_empty() {
        return Ok(0);
    }
    u32::from_str_radix(t, 16).map_err(|_| format!("not a 32-bit hex address: {text:?}"))
}

/// A plain-text listing: address, bytes, instruction. Bytes that decode to
/// nothing are shown as `.byte`, one at a time.
#[must_use]
pub fn listing(code: &[u8], base: u32) -> String {
    // `fmt::Write` for `String` never fails, so its results are ignored.
    let mut out = String::new();
    let shown = &code[..code.len().min(MAX_BYTES)];
    for line in disassemble(shown, base, Targets::Absolute) {
        let hex = line.bytes.iter().fold(String::new(), |mut s, b| {
            let _ = write!(s, "{b:02x}");
            s
        });
        let _ = match line.insn {
            Some(i) => writeln!(
                out,
                "{:08x}:  {hex:<6}  {:<10} {}",
                line.address, i.mnemonic, i.operands
            ),
            None => writeln!(
                out,
                "{:08x}:  {hex:<6}  .byte      {:#04x}",
                line.address, line.bytes[0]
            ),
        };
    }
    if code.len() > MAX_BYTES {
        let _ = writeln!(out, "... {} more bytes not shown", code.len() - MAX_BYTES);
    }
    out.trim_end().to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn one(bytes: &[u8], address: u32, targets: Targets) -> String {
        let i = decode(bytes, address, targets).expect("decodes");
        format!("{} {}", i.mnemonic, i.operands)
    }

    // Expected strings are llvm-mc's output for the same bytes.
    #[test]
    fn matches_llvm_mc_on_samples() {
        assert_eq!(one(&[0xc0, 0x20, 0x00], 0, Targets::Relative), "memw ");
        assert_eq!(
            one(&[0x60, 0x22, 0x80], 0, Targets::Relative),
            "add a2, a2, a6"
        );
        assert_eq!(
            one(&[0x82, 0xa1, 0x05], 0, Targets::Relative),
            "movi a8, 261"
        );
        assert_eq!(one(&[0x0c, 0x13], 0, Targets::Relative), "movi.n a3, 1");
        assert_eq!(
            one(&[0x00, 0xb0, 0x13], 0, Targets::Relative),
            "wsr a0, configid0"
        );
    }

    #[test]
    fn rejects_what_llvm_rejects() {
        assert!(decode(&[0x14, 0x00, 0x00], 0, Targets::Relative).is_none());
        assert!(decode(&[0x00], 0, Targets::Relative).is_none());
    }

    #[test]
    fn absolute_targets_use_the_address() {
        // j . +4 at 0x40080000
        let rel = one(&[0x06, 0x00, 0x00], 0x4008_0000, Targets::Relative);
        let abs = one(&[0x06, 0x00, 0x00], 0x4008_0000, Targets::Absolute);
        assert_eq!((rel.as_str(), abs.as_str()), ("j . +4", "j 0x40080004"));
    }

    #[test]
    fn hex_input_forms() {
        assert_eq!(parse_hex("0xc0 0x20, 00").unwrap(), [0xc0, 0x20, 0]);
        assert_eq!(
            parse_hex("c02000 # memw\n\\x0c\\x13").unwrap(),
            [0xc0, 0x20, 0, 0x0c, 0x13]
        );
        assert!(parse_hex("c0 2").is_err() && parse_hex("zz").is_err());
        assert_eq!(parse_address("0x40080000").unwrap(), 0x4008_0000);
    }

    #[test]
    fn listing_shows_undecodable_bytes() {
        let text = listing(&[0xc0, 0x20, 0x00, 0x14], 0x1000);
        assert!(text.starts_with("00001000:  c02000  memw"));
        assert!(text.ends_with(".byte      0x14"));
    }
}
